function MiniChart({ points }: { points: string }) {
  return (
    <svg className="mini-chart" viewBox="0 0 60 32">
      <path
        d={points}
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  )
}

function Coin({
  type,
  className,
}: {
  type: 'btc' | 'eth' | 'sol' | 'usdt'
  className: string
}) {
  const content =
    type === 'btc'
      ? '₿'
      : type === 'eth'
      ? '◆'
      : type === 'sol'
      ? '≋'
      : '₮'

  return (
    <div className={`coin coin-${type} ${className}`}>
      <span>{content}</span>
    </div>
  )
}

